-- 18.6 inserts a row's GIN entries sorted, so of two oversized elements it names the one
-- that sorts first — the 3 001-character `a…`, written second.
-- @setup
CREATE TABLE g (a text[]);
CREATE INDEX g_i ON g USING gin (a);
-- @test
-- @expect-error: the first oversized element in sort order
-- @expect-message
-- @profile-lock
INSERT INTO g VALUES (ARRAY['', '']);
